import{_ as e,o as a,c as n,a2 as d}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"4. Executed Test Baseline","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i0.7/part-02.md","filePath":"en/publications/implementation-case-i0.7/part-02.md","lastUpdated":1786282064000}'),r={name:"en/publications/implementation-case-i0.7/part-02.md"};function i(s,t,o,c,l,h){return a(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="_4-executed-test-baseline" tabindex="-1">4. Executed Test Baseline <a class="header-anchor" href="#_4-executed-test-baseline" aria-label="Permalink to &quot;4. Executed Test Baseline&quot;">​</a></h1><p>All primary runs were author-executed against the locked sources. Counts are reported without converting skipped tests into passes.</p><table tabindex="0"><thead><tr><th>Track</th><th style="text-align:right;">Result</th><th style="text-align:right;">Exit</th><th>Interpretation</th></tr></thead><tbody><tr><td>External S0.5 product fixture</td><td style="text-align:right;">15/15 assertions</td><td style="text-align:right;">0</td><td>Mandatory product-level C01–C14 bundle</td></tr><tr><td>CodeFlowMu built-in TMPA suite</td><td style="text-align:right;">19/19 tests</td><td style="text-align:right;">0</td><td>Product regression mapping for the criteria</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">Passed</td><td style="text-align:right;">0</td><td>Protocol tests; separate from conformance verdict</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,446 passed, 0 failed, 1 skipped</td><td style="text-align:right;">0</td><td>Full locked Runtime run</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">775/775</td><td style="text-align:right;">0</td><td>Initialized isolated product instance</td></tr><tr><td>Protocol / Runtime / Shell type checks</td><td style="text-align:right;">all passed</td><td style="text-align:right;">0</td><td>Static checks only</td></tr><tr><td>FCoP 3.2.4 source baseline</td><td style="text-align:right;">1,210 passed, 2 skipped</td><td style="text-align:right;">0</td><td>Two historical examples skipped under migrated layout</td></tr></tbody></table><p>The criterion aggregate is <strong>14 PASS / 0 PARTIAL / 0 NOT RUN / 0 FAIL</strong>. This is a product result for the fixed I0.7 bundle, not a transfer of Reference Reader results and not a universal theorem about every deployment.</p><h1 id="_5-c01–c14-product-results" tabindex="-1">5. C01–C14 Product Results <a class="header-anchor" href="#_5-c01–c14-product-results" aria-label="Permalink to &quot;5. C01–C14 Product Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.5 criterion</th><th style="text-align:right;">Verdict</th><th>Executed observation</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Nine mandatory malformed-schema classes emitted <code>SCHEMA_INVALID</code> and produced no authoritative node.</td></tr><tr><td>C02</td><td>Primary carrier and immutability</td><td style="text-align:right;"><strong>PASS</strong></td><td>Content-addressed revisions and attributable <code>CORRECTION</code> evidence remained intact; <code>parent</code> survived FCoP Markdown projection and Reader reconstruction.</td></tr><tr><td>C03</td><td>Duplicate identity</td><td style="text-align:right;"><strong>PASS</strong></td><td>Same-ID, different-content candidates remained manifested; neither won and deterministic critical-conflict quarantine was emitted.</td></tr><tr><td>C04</td><td>Stream continuity and asynchronous progress</td><td style="text-align:right;"><strong>PASS</strong></td><td>Duplicate and gap issues were reported, unrelated streams reconstructed, no missing object was invented, and arrival order did not change output.</td></tr><tr><td>C05</td><td>Role authority</td><td style="text-align:right;"><strong>PASS</strong></td><td>Denied and undetermined authority branches emitted required issues and did not mutate reconstructed state.</td></tr><tr><td>C06</td><td>Lifecycle legality</td><td style="text-align:right;"><strong>PASS</strong></td><td>Missing independent acceptance kept <code>work_state</code> at <code>review</code> and emitted both <code>LIFECYCLE_UNDETERMINED</code> and <code>ACCEPTANCE_UNDETERMINED</code>; illegal and conflicting-state branches also matched.</td></tr><tr><td>C07</td><td>Separation of duties and human control</td><td style="text-align:right;"><strong>PASS</strong></td><td>The same identity across role labels was rejected; high-risk work stayed <code>pending_human</code> until ADMIN approval evidence.</td></tr><tr><td>C08</td><td>Integrity tampering</td><td style="text-align:right;"><strong>PASS</strong></td><td>Covered-content modification caused <code>INTEGRITY_MISMATCH</code>; the object was excluded from authoritative nodes while failure evidence remained in the source manifest.</td></tr><tr><td>C09</td><td>Missing reference</td><td style="text-align:right;"><strong>PASS</strong></td><td><code>MISSING_REFERENCE</code> and <code>CLAIM_EVIDENCE_MISSING</code> remained visible; neither dependency nor completion claim was treated as satisfied.</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td style="text-align:right;"><strong>PASS</strong></td><td>Only prohibited-cycle members were quarantined; an unrelated valid node remained authoritative.</td></tr><tr><td>C11</td><td>Deterministic reconstruction</td><td style="text-align:right;"><strong>PASS</strong></td><td>All 24 permutations of a fixed four-source set produced byte-equivalent canonical results with SHA-256 <code>84e22cf795301ef0eaeaaa026154bfbef3d8cb94a49d3445484443fceaf0c85e</code>.</td></tr><tr><td>C12</td><td>Conflict preservation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Contradictory reviews remained <code>disputed</code>; an unauthorized DEV decision remained evidence but could not clear the conflict, while an assigned PM with <code>resolve_review_conflict</code> permission resolved it.</td></tr><tr><td>C13</td><td>Recovery</td><td style="text-align:right;"><strong>PASS</strong></td><td>Fresh Readers reconstructed lifecycle, responsibility, unresolved dependency, failure/recovery, parent-child state, and <code>CHILD_WORK_OPEN</code> identically.</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Only the accepted authorized chain reached archive; task, report, review, acceptance, and transition history remained reconstructable.</td></tr></tbody></table><h1 id="_6-v1-4-0-to-v1-4-1-repair-analysis" tabindex="-1">6. V1.4.0 to V1.4.1 Repair Analysis <a class="header-anchor" href="#_6-v1-4-0-to-v1-4-1-repair-analysis" aria-label="Permalink to &quot;6. V1.4.0 to V1.4.1 Repair Analysis&quot;">​</a></h1><p>The repair comparison is intentionally narrow. V1.4.0 already passed C02 and C07; its two failures were C06 and C12.</p><h2 id="_6-1-c06-—-lifecycle-is-not-acceptance" tabindex="-1">6.1 C06 — lifecycle is not acceptance <a class="header-anchor" href="#_6-1-c06-—-lifecycle-is-not-acceptance" aria-label="Permalink to &quot;6.1 C06 — lifecycle is not acceptance&quot;">​</a></h2><p>V1.4.0 allowed <code>review → done</code> when lifecycle evidence appeared sufficient even though independent acceptance was absent. That collapsed process progression into business acceptance. V1.4.1 calculates the two judgments separately: without independent acceptance, work remains at <code>review</code> and both lifecycle and acceptance uncertainty are emitted. The product therefore does not manufacture completion from an incomplete authority chain.</p><h2 id="_6-2-c12-—-only-an-authorized-resolver-may-clear-a-conflict" tabindex="-1">6.2 C12 — only an authorized resolver may clear a conflict <a class="header-anchor" href="#_6-2-c12-—-only-an-authorized-resolver-may-clear-a-conflict" aria-label="Permalink to &quot;6.2 C12 — only an authorized resolver may clear a conflict&quot;">​</a></h2><p>V1.4.0 preserved conflicting reviews but allowed a later unauthorized decision to clear their disputed state. V1.4.1 retains the unauthorized DEV decision as evidence, emits the authority issue, and leaves <code>UNRESOLVED_CONFLICT</code> in force. Only a decision object from an assigned actor with <code>resolve_review_conflict</code> permission—demonstrated with PM—can resolve the conflict.</p><h2 id="_6-3-regression-boundary" tabindex="-1">6.3 Regression boundary <a class="header-anchor" href="#_6-3-regression-boundary" aria-label="Permalink to &quot;6.3 Regression boundary&quot;">​</a></h2><p>C03 continues to govern same-ID, different-content candidate conflicts. C10 continues to govern prohibited reference cycles. Neither was merged into C12, and both continue to pass. This matters because a successful patch that weakens or redefines neighboring criteria would not demonstrate S0.5 conformance.</p><h1 id="_7-wp-13-multi-agent-evidence-gating-case" tabindex="-1">7. WP-13 Multi-Agent Evidence-Gating Case <a class="header-anchor" href="#_7-wp-13-multi-agent-evidence-gating-case" aria-label="Permalink to &quot;7. WP-13 Multi-Agent Evidence-Gating Case&quot;">​</a></h1><p>WP-13 addresses a different question from the C01–C14 bundle: can a role-separated workflow prevent an unverified completion claim from becoming an authoritative delivery fact?</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>completion-meaning claim</span></span>
<span class="line"><span>        ↓ persistent evidence incomplete</span></span>
<span class="line"><span>PM fact check → hold / do not release / do not dispatch QA</span></span>
<span class="line"><span>        ↓ same-task recovery</span></span>
<span class="line"><span>DEV commit + report</span></span>
<span class="line"><span>        ↓ separate role</span></span>
<span class="line"><span>QA rerun and report</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>authorized Gate C decision</span></span></code></pre></div><p>The initial DEV subexecution used completion-meaning language while exit status, tests, commit, and formal report were not all established. PM checked persistent facts, withheld release, and did not dispatch QA. After recovery, DEV produced the missing evidence and role-separated QA reran tests and checks. A later Gate C record accepted the business delivery; activation, push/publication, and archive remained separate decisions.</p><p>The case demonstrates evidence gating, role separation, same-task recovery, and staged authority. It does <strong>not</strong> prove that a model ceased to hallucinate, that every false claim will be detected, or that the original V3 snapshot already contained terminal approval. Its snapshot boundary records <code>runtime_bound: false</code> and TASK-019/020 at <code>review / pending</code>; later acceptance must not be back-projected into that earlier snapshot.</p>`,19)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
